<div id="app"></div>
<div class="help btn" onclick="alert('How can we help?')"><span class="help-icon">☷</span>Help</div>

<script>
const A='__PLACEHOLDER_ASSETS_BASE_DIR__/';
const app=document.getElementById('app');
let selectedDate=false;

function header(){
 return `<header class="topbar"><div class="top-inner">
  <span class="micro">Visit Disney.com</span><div class="logo">Walt Disney World</div>
  <nav class="nav">
   <a class="btn" onclick="showHome()">Tickets & Parks</a><a class="btn">Places to Stay</a><a class="btn">Things to Do</a><a class="btn">Shop</a><a class="btn">Help & Rules</a><a class="btn">🛒 Cart</a><a class="btn">◉ My Disney Experience</a>
  </nav><span class="account">United States (English)　<input class="search" placeholder="Search or ask a question"></span>
 </div></header>`;
}
function showHome(){
 app.innerHTML=`${header()}<main class="page">
 <section class="home-hero">
  <div class="booking"><strong>Build Your Vacation</strong><div class="booking-group">Dates<br><b>Check In　 -　 Check Out　 ▣</b></div><div class="booking-group">Adults (18+)<div class="counter"><span class="circle">−</span>2<span class="circle">+</span></div></div><div class="booking-group">Children<div class="counter"><span class="circle">−</span>0<span class="circle">+</span></div></div><div class="booking-group">All Resort Hotels<br><b>All Resort Hotels　⌄</b></div><div>□ Accessible Rooms</div><button class="rate-btn btn">View Rates</button></div>
  <div class="home-copy"><h2>Welcome to</h2><h1>The Most Magical Place On Earth</h1><button class="pill btn" onclick="showTickets()">▦　Explore Resort Hotels</button><button class="pill btn" onclick="showTickets()">▣　Get Tickets</button></div>
 </section><section class="home-bottom"><h2>Save with Special Offers</h2></section></main>`;
}
function showTickets(){
 app.innerHTML=`${header()}<main class="page tickets">
 <section class="ticket-hero"><div class="crumb">⌂ Home › Admission</div><h1>Walt Disney World Theme Park Tickets</h1></section>
 <div class="resident">Special tickets and prices may be available for Florida Residents. <a class="link btn">Log in</a></div>
 <div class="ticket-content"><section class="intro"><p>Discover 4 amazing theme parks and 2 water parks near Orlando, Florida—providing plenty of fun for a multi-day stay. Walt Disney World ticket prices below are for a one-day ticket (unless otherwise noted) before tax, for ages 10+.</p><p>To view or make changes to tickets you've already purchased, visit <a class="link btn">My Plans</a>.</p></section>
 <h2 class="section-title">Special Offers</h2>
 <div class="offer-card"><div class="offer-main"><h2>3-Day, 3-Park Ticket</h2><ul><li>Admission to <b>Disney’s Hollywood Studios, EPCOT and Disney’s Animal Kingdom theme park only.</b> One admission per theme park. One theme park per day.</li><li><b>Does not include Magic Kingdom park.</b></li><li>Valid for start dates from April 6 through September 22, 2025. Ticket must be used within 5 days of selected start date.</li></ul><a class="link btn" onclick="openDetails()">View Details</a></div><div class="offer-price"><small>3-day ticket (Ages 10+) from:</small><div class="price">$89.00 / Day</div><small>($267.00 per ticket)</small><button class="blue-btn btn" onclick="showPurchase()">Continue</button></div></div>
 <div class="offer-card"></div></div></main>`;
}
function openDetails(){
 const m=document.createElement('div');m.className='modal-back';m.id='modal';
 m.innerHTML=`<div class="modal"><button class="modal-close btn" onclick="closeDetails()">×</button><h2>3-Day, 3-Park Ticket</h2><div class="modal-scroll">
 <p>Guests can purchase a 3-Day, 3-Park Ticket to <b>Disney’s Hollywood Studios, EPCOT and Disney’s Animal Kingdom theme park only</b> starting at $89 per day, plus tax (total price starting at $267, plus tax). This is a date-based ticket with start dates from April 6 through September 22, 2025. Ticket must be used within 5 days of selected start date.</p>
 <p>Limit one admission per theme park and one theme park per day—for a total of 3 admissions, on 3 separate days. Tickets may not be used to enter the same theme park more than once. <b>Not valid for admission to Magic Kingdom park.</b></p>
 <p>This ticket <b>does not require theme park reservations</b> to enter the parks.</p>
 <p>All tickets and options are nontransferable and nonrefundable, and exclude activities/events separately priced.</p>
 <p>Admission is subject to capacity closures and other restrictions.</p>
 <p>Parks, attractions and other offerings are subject to availability, closures and change or cancellation without notice or liability.</p>
 <p><u><b>Available Options</b></u></p><p><b>Water Park and Sports option:</b> Visit one theme park per day, plus enjoy 3 visits to a water park or other Walt Disney World fun.</p>
 <ul><li>A Walt Disney World water park</li><li>ESPN Wide World of Sports Complex</li><li>Disney’s Oak Trail Golf Course</li><li>FootGolf at Disney's Oak Trail</li></ul>
 </div></div>`;
 document.body.appendChild(m);
}
function closeDetails(){document.getElementById('modal')?.remove()}
function showPurchase(){
 app.innerHTML=`${header()}<main class="purchase"><div class="purchase-hero"></div><div class="ticket-content">
 <section class="purchase-intro"><h1>3-Day, 3-Park Ticket</h1><p>Enjoy admission to <b>Disney’s Hollywood Studios, EPCOT and Disney’s Animal Kingdom theme park only.</b> Limit of one admission per theme park and one theme park per day. <b>Not valid for admission to Magic Kingdom park.</b></p><p>Ticket valid for start dates from April 6 through September 22, 2025. Ticket must be used within 5 days of the selected start date.</p><a class="link btn" onclick="openDetails()">View Details</a></section>
 <section class="purchase-section"><h2>Select the Number of Days</h2><p>Price (USD) is per day, per ticket (Age 10+) before tax.</p><div class="days"><div class="day"><div class="day-num">3</div><small>From</small><br><b>$89</b><br><small>per day</small></div></div></section>
 <section class="calendar-wrap"><div class="calendar-head"><h2>Choose the Start Date of Your 3-Day Ticket</h2><p>Calendar shows the price per day for 3-day ticket (Ages 10+).</p><a class="link btn">▣ See which month(s) offer the lowest price and check park hours and events</a></div><div class="month-nav"><span class="btn">‹</span><b>August <span style="font-weight:normal">2025</span></b><span class="btn">›</span></div><div class="calendar" id="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="weekday">${x}</div>`).join('')}${calendarCells()}</div><div id="selection"></div></section>
 <section class="ticket-count"><h2>Select the Number of Tickets</h2><p>Please note that children younger than age 3 don’t need a ticket.</p><div class="count-row"><div class="count-item"><div class="count-label">Ages 10+<small>$267.00/ticket</small></div><span class="count-control btn">−</span><span>1</span><span class="count-control btn">+</span></div><div class="count-item"><div class="count-label">Ages 3-9<small>$267.00/ticket</small></div><span class="count-control btn">−</span><span>0</span><span class="count-control btn">+</span></div></div><div class="details"><h3>Important Ticket Details</h3><p>▣　<b>Valid Ticket Dates</b><br>　　Your tickets are valid for admission to one theme park each day on any 3 days from Aug 28, 2025 through Sep 1, 2025. Tickets are nonrefundable.</p><p>♟　<b>3-Day, 3-Park Ticket Information</b><br>　　<b>Not valid for admission to Magic Kingdom park.</b> The 3-Day, 3-Park Ticket is valid for admission to Disney’s Hollywood Studios, EPCOT and Disney’s Animal Kingdom theme park only.</p></div></section></div>
 <section class="current"><div class="current-inner"><h2>Current Selections</h2><b>Walt Disney World 3-Day 3-Park Ticket</b><br>Valid any 3 days from Thu, Aug 28, 2025 – Mon, Sep 1, 2025.<div class="summary-line"><span>1 × Ages 10+　($267.00/ticket)</span><span>$267.00</span></div><div class="subtotal">Subtotal $284.36 <small>USD</small></div><div class="continue-area"><button class="green-btn btn" onclick="showCart()">Continue</button></div></div></section></main>`;
}
function calendarCells(){
 let s=''; for(let i=1;i<=31;i++){let cls=i>=25?'active':'';s+=`<div class="cell ${cls} btn" onclick="selectDate(this,${i})"><span>${i}</span>${i>=25?'<span class="cost">$89+</span>':''}</div>`}return s;
}
function selectDate(el,d){
 document.querySelectorAll('.cell').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');selectedDate=true;
 document.getElementById('selection').innerHTML=`<div class="selection-info"><div><small>Tickets can be used on non-consecutive days!</small><br>Use any 3 days from Aug ${d}, 2025 – Sep 1, 2025.</div><div>From $89.00 /day × 3 days<br>From $267.00 /ticket (Ages 10+)</div></div>`;
}
function showCart(){
 app.innerHTML=`${header()}<main class="cart-page"><div class="cart-panel"><h1>Your Cart <a class="link btn" style="float:right;font-size:14px">Retrieve a Different Cart</a></h1><img class="cart-banner" src="${A}041.png" width="920" height="110"><div class="cart-table-head">Unit Price　　 Quantity　　 Price</div><div class="cart-items"><div class="cart-title">🏷　 Theme Park Tickets</div><div class="cart-item"><div class="detail"><strong>Walt Disney World 3-Day 3-Park Ticket (Ages 10+)</strong>Valid any 3 days from Thu, Aug 28, 2025 through Mon, Sep 1, 2025.<br><a class="link btn">View Important Details</a></div><span>$ 267.00</span><span>1</span><span>$ 267.00</span><span class="btn">⊗</span></div><div class="cart-item"><div class="detail"><strong>Walt Disney World 3-Day 3-Park Ticket (Ages 10+)</strong>Valid any 3 days from Wed, Aug 27, 2025 through Sun, Aug 31, 2025.<br><a class="link btn">View Important Details</a></div><span>$ 267.00</span><span>2</span><span>$ 534.00</span><span class="btn">⊗</span></div></div><div class="cart-bottom"><div class="compare btn">▧ Compare Vacation Offers</div><div class="cart-total"><div>Tax　　　　　 $52.08</div><div><b>Subtotal　<strong>$853.08</strong> USD</b></div><div class="cart-actions"><button class="save btn">Save Cart</button><button class="cart-continue btn">Continue</button></div><small>🟢 See Important Details above.</small><br><br><small>Vacation Questions? Call 407-934-7639</small></div></div></div></main>`;
}
showHome();
</script>
</body>
</html>
